/// <summary>
/// MPJ-21310 Entry point for processes that need to check substitutes
/// for sales order lines at point of reservation.
/// </summary>
class METSalesItemSubstitutionApplyAtReservation
{

}

Method.Source:
public static boolean checkLine(
    SalesLine       _salesLine, 
    boolean         _interactive = false)
{
    METSalesItemSubstitution sub = METSalesItemSubstitution::construct(
        _salesLine,
        _salesLine.metSalesLine(true),
        _salesLine.inventDim(), 
        METSalesItemSubstitutionEventSource::Reservation,            
        _interactive);
    return sub.run();
}

public static void main(Args _args)
{
    SalesLine salesLine = _args.record();
    if(!salesLine)
    {
        throw error(error::missingRecord(funcName()));
    }
    if(!METSalesItemSubstitutionApplyAtReservation::checkLine(salesLine, true))
    {
        throw error("Item substitution failed validation");
    }
}
